from jsonb_to_recordset($q$[{"id":700,"materia":"cont","nivel":3,"enunciado":"Pela Lei 6.404/1976, a reserva legal corresponde a:","opcoes":["5% do lucro líquido, até 20% do capital","10% do lucro, até 30% do capital","5% do lucro, sem limite","20% do lucro, até 5% do capital"],"explicacao":"Art. 193."},{"id":701,"materia":"cont","nivel":3,"enunciado":"As perdas estimadas com créditos de liquidação duvidosa são conta:","opcoes":["Redutora de clientes, no ativo","Do passivo circulante","De receita operacional","Do patrimônio líquido"],"explicacao":"Têm saldo credor e reduzem as duplicatas a receber."},{"id":702,"materia":"cont","nivel":3,"enunciado":"Um seguro anual pago adiantado é registrado inicialmente como:","opcoes":["Despesa antecipada no ativo","Despesa inteira do mês","Passivo circulante","Receita antecipada"],"explicacao":"Pela competência, vira despesa mês a mês, conforme a cobertura passa."},{"id":703,"materia":"cont","nivel":3,"enunciado":"Uma máquina de R$ 60.000 tem depreciação acumulada de R$ 24.000. Qual o valor contábil?","opcoes":["R$ 36.000","R$ 84.000","R$ 24.000","R$ 60.000"],"explicacao":"Valor contábil = custo − depreciação acumulada."},{"id":704,"materia":"cont","nivel":3,"enunciado":"Pelo CPC 00, as características qualitativas FUNDAMENTAIS são:","opcoes":["Relevância e representação fidedigna","Comparabilidade e verificabilidade","Tempestividade e compreensibilidade","Prudência e uniformidade"],"explicacao":"As de melhoria são comparabilidade, verificabilidade, tempestividade e compreensibilidade."},{"id":705,"materia":"cont","nivel":3,"enunciado":"Qual destas é característica qualitativa de MELHORIA, pelo CPC 00?","opcoes":["Comparabilidade","Relevância","Representação fidedigna","Materialidade"],"explicacao":"Materialidade é um aspecto da relevância."},{"id":706,"materia":"cont","nivel":3,"enunciado":"Pela noção de entidade:","opcoes":["O patrimônio da empresa não se confunde com o dos sócios","A empresa funcionará por tempo indeterminado","Receitas e despesas seguem a competência","Os registros usam sempre o valor original"],"explicacao":"As contas pessoais dos sócios não se misturam com as da empresa."},{"id":707,"materia":"cont","nivel":3,"enunciado":"O pressuposto de que a entidade continuará operando no futuro previsível é o da:","opcoes":["Continuidade","Entidade","Oportunidade","Prudência"],"explicacao":"Se a empresa for encerrar, os ativos passam a ser avaliados de outra forma."},{"id":708,"materia":"cont","nivel":3,"enunciado":"Os juros de um empréstimo, apropriados mês a mês, são:","opcoes":["Despesas financeiras","Receitas financeiras","Custos de estoque","Ativo imobilizado"],"explicacao":"Reduzem o resultado do período em que ocorrem."},{"id":709,"materia":"cont","nivel":3,"enunciado":"O balancete de verificação serve para:","opcoes":["Conferir se débitos e créditos batem","Apurar o lucro tributável do ano","Substituir o balanço patrimonial","Registrar as vendas em ordem"],"explicacao":"Pelas partidas dobradas, a soma dos saldos devedores deve igualar a dos credores."},{"id":710,"materia":"cont","nivel":4,"enunciado":"Pela Lei 6.404/1976, a Demonstração do Valor Adicionado (DVA) é obrigatória para:","opcoes":["Companhias abertas","Todas as empresas","Microempresas","Sociedades limitadas"],"explicacao":"Art. 176, V."},{"id":711,"materia":"cont","nivel":4,"enunciado":"A DFC é dispensada para a companhia fechada com PL, na data do balanço, inferior a:","opcoes":["R$ 2 milhões","R$ 1 milhão","R$ 10 milhões","R$ 240 mil"],"explicacao":"Art. 176, § 6º, da Lei 6.404/1976."},{"id":712,"materia":"cont","nivel":4,"enunciado":"Na DFC, a compra de um imobilizado à vista é atividade de:","opcoes":["Investimento","Operacional","Financiamento","Nenhuma, não afeta o caixa"],"explicacao":"Aquisição e venda de ativos de longo prazo são atividades de investimento."},{"id":713,"materia":"cont","nivel":4,"enunciado":"Na DFC, a obtenção de um empréstimo bancário é atividade de:","opcoes":["Financiamento","Investimento","Operacional","Nenhuma, não afeta o caixa"],"explicacao":"Captação e pagamento de recursos de credores e sócios são financiamento."},{"id":714,"materia":"cont","nivel":4,"enunciado":"Na DFC pelo método indireto, a depreciação do período é:","opcoes":["Somada ao lucro líquido","Subtraída do lucro líquido","Lançada em investimentos","Lançada em financiamentos"],"explicacao":"É despesa que não sai do caixa, então é adicionada de volta ao lucro."},{"id":715,"materia":"cont","nivel":4,"enunciado":"Equipamento de R$ 100.000, valor residual R$ 10.000 e vida útil de 5 anos. Qual a depreciação anual linear?","opcoes":["R$ 18.000","R$ 20.000","R$ 22.000","R$ 9.000"],"explicacao":"(100.000 − 10.000) ÷ 5 = 18.000."},{"id":716,"materia":"cont","nivel":4,"enunciado":"Pela soma dos dígitos, um bem com vida útil de 4 anos deprecia no 1º ano qual fração do valor depreciável?","opcoes":["4/10","1/4","1/10","3/10"],"explicacao":"Soma dos dígitos: 1 + 2 + 3 + 4 = 10. No 1º ano usa-se 4/10, no 2º 3/10, e assim por diante."},{"id":717,"materia":"cont","nivel":4,"enunciado":"Lucro bruto R$ 100.000, despesas operacionais R$ 40.000 e IR/CSLL R$ 15.000. Qual o lucro líquido?","opcoes":["R$ 45.000","R$ 60.000","R$ 55.000","R$ 85.000"],"explicacao":"100.000 − 40.000 = 60.000 antes dos tributos; 60.000 − 15.000 = 45.000."},{"id":718,"materia":"cont","nivel":4,"enunciado":"Na DRE, a receita líquida é a receita bruta menos:","opcoes":["Deduções, como devoluções e tributos","O custo das mercadorias vendidas","As despesas administrativas","O imposto de renda do período"],"explicacao":"Depois, receita líquida menos CMV dá o lucro bruto."},{"id":719,"materia":"cont","nivel":4,"enunciado":"Venda a prazo de R$ 1.000, com ICMS de 18% incluso no preço. Qual a receita líquida?","opcoes":["R$ 820","R$ 1.000","R$ 1.180","R$ 180"],"explicacao":"O ICMS sobre vendas é dedução da receita bruta: 1.000 − 180 = 820."},{"id":720,"materia":"cont","nivel":4,"enunciado":"Qual destes eventos é um fato contábil permutativo?","opcoes":["Compra de veículo a prazo","Pagamento de salários","Recebimento de juros","Venda de mercadoria com lucro"],"explicacao":"Aumentam o ativo e o passivo no mesmo valor, e o PL não muda."},{"id":721,"materia":"cont","nivel":4,"enunciado":"A integralização de capital em dinheiro pelos sócios provoca:","opcoes":["Aumento do ativo e do PL","Aumento do ativo e do passivo","Redução do ativo e do PL","Aumento de receita"],"explicacao":"Débito em caixa (ativo) e crédito em capital social (PL)."},{"id":722,"materia":"cont","nivel":4,"enunciado":"Passivo exigível R$ 300 mil e PL R$ 200 mil. Qual a participação de capital de terceiros (PE ÷ PL)?","opcoes":["150%","60%","40%","66%"],"explicacao":"300 ÷ 200 = 1,5 = 150%."},{"id":723,"materia":"cont","nivel":4,"enunciado":"A liquidez geral é calculada por:","opcoes":["(AC + RLP) ÷ (PC + PNC)","AC ÷ PC","Disponível ÷ PC","(AC − estoques) ÷ PC"],"explicacao":"Considera também o realizável e o exigível de longo prazo."},{"id":724,"materia":"cont","nivel":4,"enunciado":"Pelo CPC 25, a provisão é reconhecida quando há obrigação presente, saída de recursos provável e:","opcoes":["Estimativa confiável do valor","Pagamento já efetuado","Decisão judicial definitiva","Autorização da assembleia"],"explicacao":"Sem esses três requisitos, não se reconhece a provisão."},{"id":725,"materia":"cont","nivel":4,"enunciado":"Pelo CPC 25, um passivo contingente com saída de recursos apenas possível deve ser:","opcoes":["Divulgado em nota explicativa","Reconhecido no balanço","Ignorado completamente","Lançado como despesa"],"explicacao":"Se a saída for remota, nem a divulgação é exigida."},{"id":726,"materia":"cont","nivel":4,"enunciado":"A redução ao valor recuperável de ativos (impairment) é tratada no:","opcoes":["CPC 01","CPC 16","CPC 25","CPC 27"],"explicacao":"CPC 16 trata de estoques, CPC 25 de provisões e CPC 27 do imobilizado."},{"id":727,"materia":"cont","nivel":4,"enunciado":"As ações em tesouraria são apresentadas como:","opcoes":["Redução do patrimônio líquido","Aplicação no ativo circulante","Investimento no não circulante","Obrigação no passivo circulante"],"explicacao":"São ações da própria empresa recompradas; ficam como conta redutora do PL."},{"id":728,"materia":"cont","nivel":4,"enunciado":"Um adiantamento feito a fornecedor é classificado como:","opcoes":["Ativo (direito)","Passivo","Receita","Patrimônio líquido"],"explicacao":"A empresa tem o direito de receber a mercadoria ou o serviço."},{"id":729,"materia":"cont","nivel":4,"enunciado":"Salários de dezembro pagos só em janeiro geram, em dezembro:","opcoes":["Despesa e passivo","Apenas despesa em janeiro","Ativo em dezembro","Receita em janeiro"],"explicacao":"Pela competência, a despesa é de dezembro, com obrigação de salários a pagar."},{"id":730,"materia":"cont","nivel":4,"enunciado":"Num balancete, a soma dos saldos devedores é R$ 500 mil. A soma dos saldos credores deve ser:","opcoes":["R$ 500 mil","R$ 250 mil","R$ 1 milhão","Zero"],"explicacao":"Pelas partidas dobradas, as duas somas devem ser iguais."},{"id":731,"materia":"civ","nivel":1,"enunciado":"Segundo o Código Civil, a personalidade civil da pessoa começa:","opcoes":["Do nascimento com vida","Da concepção","Dos 18 anos completos","Do registro em cartório"],"explicacao":"Art. 2º. A lei põe a salvo, desde a concepção, os direitos do nascituro."},{"id":732,"materia":"civ","nivel":1,"enunciado":"Com quantos anos se atinge a maioridade civil?","opcoes":["18","21","16","20"],"explicacao":"Art. 5º do Código Civil."},{"id":733,"materia":"civ","nivel":1,"enunciado":"A existência da pessoa natural termina com:","opcoes":["A morte","A maioridade","O casamento","A emancipação"],"explicacao":"Art. 6º do Código Civil."},{"id":734,"materia":"civ","nivel":1,"enunciado":"Os menores de 16 anos são:","opcoes":["Absolutamente incapazes","Relativamente incapazes","Plenamente capazes","Emancipados"],"explicacao":"Art. 3º. Desde 2015, essa é a única hipótese de incapacidade absoluta."},{"id":735,"materia":"civ","nivel":1,"enunciado":"O domicílio da pessoa natural é o lugar onde ela:","opcoes":["Reside com ânimo definitivo","Nasceu e foi registrada em cartório","Esteve por último em viagem a passeio","Votou na última eleição municipal"],"explicacao":"Art. 70 do Código Civil."},{"id":736,"materia":"civ","nivel":1,"enunciado":"Bens que podem ser transportados sem alterar sua substância são:","opcoes":["Móveis","Imóveis","Fungíveis","Públicos"],"explicacao":"Art. 82 do Código Civil."},{"id":737,"materia":"civ","nivel":1,"enunciado":"Um terreno é um bem:","opcoes":["Imóvel","Móvel","Consumível","Fungível"],"explicacao":"É o solo e tudo o que se lhe incorporar (art. 79)."},{"id":738,"materia":"civ","nivel":1,"enunciado":"A propriedade de um imóvel comprado se transfere com:","opcoes":["O registro no cartório de imóveis","A simples assinatura do contrato","O pagamento da primeira parcela","A entrega das chaves ao comprador"],"explicacao":"Art. 1.245 do Código Civil."},{"id":739,"materia":"civ","nivel":1,"enunciado":"Os pais podem emancipar o filho que tenha pelo menos:","opcoes":["16 anos","14 anos","12 anos","17 anos"],"explicacao":"Art. 5º, parágrafo único, I, por instrumento público."},{"id":740,"materia":"civ","nivel":1,"enunciado":"O Código Civil em vigor é de:","opcoes":["2002","1916","1988","2015"],"explicacao":"Lei 10.406/2002, em vigor desde 2003."},{"id":741,"materia":"civ","nivel":2,"enunciado":"São relativamente incapazes, entre outros:","opcoes":["Os maiores de 16 e menores de 18 anos","Os menores de 16 anos de idade","Os maiores de 70 anos de idade","Os que não sabem ler nem escrever"],"explicacao":"Art. 4º, I, do Código Civil."},{"id":742,"materia":"civ","nivel":2,"enunciado":"Quando a lei não fixa prazo menor, a prescrição ocorre em:","opcoes":["10 anos","20 anos","5 anos","3 anos"],"explicacao":"Art. 205 do Código Civil."},{"id":743,"materia":"civ","nivel":2,"enunciado":"A pretensão de reparação civil prescreve em:","opcoes":["3 anos","10 anos","5 anos","1 ano"],"explicacao":"Art. 206, § 3º, V."},{"id":744,"materia":"civ","nivel":2,"enunciado":"A prescrição atinge:","opcoes":["A pretensão","O direito potestativo","A capacidade civil","A personalidade jurídica"],"explicacao":"A decadência é que extingue o próprio direito potestativo."},{"id":745,"materia":"civ","nivel":2,"enunciado":"O negócio jurídico celebrado por absolutamente incapaz é:","opcoes":["Nulo","Anulável","Válido","Inexistente sempre"],"explicacao":"Art. 166, I."},{"id":746,"materia":"civ","nivel":2,"enunciado":"O negócio celebrado por relativamente incapaz, sem assistência, é:","opcoes":["Anulável","Nulo","Válido","Inexistente"],"explicacao":"Art. 171, I."},{"id":747,"materia":"civ","nivel":2,"enunciado":"Quem, por ato ilícito, causa dano a outrem fica obrigado a:","opcoes":["Repará-lo","Ser preso","Pagar multa ao Estado","Pedir desculpas formais"],"explicacao":"Art. 927 do Código Civil."},{"id":748,"materia":"civ","nivel":2,"enunciado":"Qual destes é pessoa jurídica de direito público interno?","opcoes":["O município","A fundação privada","O partido político","A sociedade empresária"],"explicacao":"Art. 41. Os partidos políticos são pessoas jurídicas de direito privado."},{"id":749,"materia":"civ","nivel":2,"enunciado":"Os partidos políticos são pessoas jurídicas de direito:","opcoes":["Privado","Público interno","Público externo","Misto"],"explicacao":"Art. 44, V."},{"id":750,"materia":"civ","nivel":2,"enunciado":"A posse de boa-fé é aquela em que o possuidor:","opcoes":["Ignora o vício que impede a aquisição","Sabe que a coisa pertence a outra pessoa","Usa a força para se manter na coisa","Já pagou todo o preço combinado"],"explicacao":"Art. 1.201 do Código Civil."},{"id":751,"materia":"civ","nivel":3,"enunciado":"Na regra geral, a usucapião extraordinária de imóvel exige posse por:","opcoes":["15 anos","10 anos","5 anos","20 anos"],"explicacao":"Art. 1.238. O prazo cai para 10 anos se houver moradia habitual ou obras produtivas."},{"id":752,"materia":"civ","nivel":3,"enunciado":"A usucapião especial urbana (art. 183 da CF) exige área de até:","opcoes":["250 m² e 5 anos de posse","250 m² e 10 anos de posse","500 m² e 5 anos de posse","50 hectares e 5 anos de posse"],"explicacao":"Para moradia, sem ser dono de outro imóvel. 50 hectares é da usucapião rural."},{"id":753,"materia":"civ","nivel":3,"enunciado":"São defeitos do negócio jurídico, entre outros:","opcoes":["Erro, dolo e coação","Simulação e boa-fé","Termo e encargo","Prescrição e decadência"],"explicacao":"Também lesão, estado de perigo e fraude contra credores."},{"id":754,"materia":"civ","nivel":3,"enunciado":"A simulação torna o negócio jurídico:","opcoes":["Nulo","Anulável","Válido","Apenas ineficaz"],"explicacao":"Art. 167, subsistindo o que se dissimulou, se válido na substância e na forma."},{"id":755,"materia":"civ","nivel":3,"enunciado":"O prazo para anular negócio feito sob coação é de:","opcoes":["4 anos, de quando ela cessar","2 anos, da celebração","10 anos, da celebração","1 ano, da descoberta"],"explicacao":"Art. 178, I."},{"id":756,"materia":"civ","nivel":3,"enunciado":"A responsabilidade civil objetiva independe de:","opcoes":["Culpa","Dano","Nexo causal","Conduta"],"explicacao":"Sem dano ou nexo causal não há dever de indenizar."},{"id":757,"materia":"civ","nivel":3,"enunciado":"Os pais respondem pelos atos dos filhos menores sob sua autoridade:","opcoes":["Independentemente de culpa sua","Somente se provada a sua culpa","Nunca, só o filho responde","Apenas se o ato for crime"],"explicacao":"Arts. 932, I, e 933 do Código Civil."},{"id":758,"materia":"civ","nivel":3,"enunciado":"A cláusula penal num contrato é:","opcoes":["Multa prevista para o descumprimento","Cláusula que prevê prisão do devedor","Regra de foro para ações penais","Taxa de juros cobrada no contrato"],"explicacao":"Arts. 408 a 416 do Código Civil."},{"id":759,"materia":"civ","nivel":3,"enunciado":"São herdeiros necessários:","opcoes":["Descendentes, ascendentes e cônjuge","Irmãos, sobrinhos e tios do falecido","Apenas os filhos menores de idade","Primos, cunhados e afilhados"],"explicacao":"Art. 1.845 do Código Civil."},{"id":760,"materia":"civ","nivel":3,"enunciado":"A legítima, parte reservada aos herdeiros necessários, corresponde a:","opcoes":["Metade dos bens","Um terço dos bens","Todos os bens","Um quarto dos bens"],"explicacao":"Art. 1.846. A outra metade pode ir para testamento."},{"id":761,"materia":"civ","nivel":4,"enunciado":"Pelo art. 50 do Código Civil, a desconsideração da personalidade jurídica exige abuso por:","opcoes":["Desvio de finalidade ou confusão patrimonial","Simples insolvência da empresa","Mera inadimplência de um contrato","Mudança de endereço da sede"],"explicacao":"Redação dada pela Lei 13.874/2019."},{"id":762,"materia":"civ","nivel":4,"enunciado":"Na ausência, a sucessão provisória pode ser requerida depois de arrecadados os bens e passado:","opcoes":["1 ano, ou 3 se deixou procurador","6 meses, em qualquer caso","10 anos, em qualquer caso","5 anos, ou 10 com procurador"],"explicacao":"Art. 26 do Código Civil."},{"id":763,"materia":"civ","nivel":4,"enunciado":"Duas pessoas morrem na mesma ocasião e não se sabe quem morreu primeiro. Nesse caso:","opcoes":["Presumem-se mortas ao mesmo tempo","Presume-se que o mais velho morreu antes","Presume-se que o mais novo morreu antes","Decide-se por sorteio judicial"],"explicacao":"É a comoriência, prevista no art. 8º."},{"id":764,"materia":"civ","nivel":4,"enunciado":"Na comunhão parcial de bens, em regra, comunicam-se:","opcoes":["Os bens comprados durante o casamento","Os bens que cada um tinha antes","Os bens recebidos por herança","Os bens de uso pessoal e profissional"],"explicacao":"Arts. 1.658 e 1.659 do Código Civil."},{"id":765,"materia":"civ","nivel":4,"enunciado":"Sem pacto antenupcial, o regime de bens do casamento é o da:","opcoes":["Comunhão parcial","Comunhão universal","Separação total","Participação final nos aquestos"],"explicacao":"Art. 1.640 do Código Civil."},{"id":766,"materia":"civ","nivel":4,"enunciado":"O Código Civil prevê separação obrigatória de bens para quem se casa com mais de:","opcoes":["70 anos","60 anos","65 anos","80 anos"],"explicacao":"Art. 1.641, II. Em 2024, o STF admitiu que os noivos afastem essa regra por escritura pública."},{"id":767,"materia":"civ","nivel":4,"enunciado":"Evicção é:","opcoes":["Perda da coisa para terceiro com direito anterior","Defeito oculto que torna a coisa imprópria","Atraso do vendedor na entrega da coisa","Desistência do comprador antes da entrega"],"explicacao":"O alienante responde pela evicção (art. 447)."},{"id":768,"materia":"civ","nivel":4,"enunciado":"Vícios redibitórios são:","opcoes":["Defeitos ocultos que tornam a coisa imprópria","Perda da coisa para terceiro com direito anterior","Atraso do vendedor na entrega da coisa","Desistência do comprador antes da entrega"],"explicacao":"Art. 441 do Código Civil."},{"id":769,"materia":"civ","nivel":4,"enunciado":"O prazo para reclamar de vício redibitório em bem imóvel é de:","opcoes":["1 ano","30 dias","90 dias","5 anos"],"explicacao":"Art. 445. Para bem móvel, o prazo é de 30 dias."},{"id":770,"materia":"civ","nivel":4,"enunciado":"A pretensão de cobrar aluguéis de prédios prescreve em:","opcoes":["3 anos","1 ano","5 anos","10 anos"],"explicacao":"Art. 206, § 3º, I."},{"id":771,"materia":"pciv","nivel":1,"enunciado":"O Código de Processo Civil em vigor é de:","opcoes":["2015","1973","2002","1988"],"explicacao":"Lei 13.105/2015, em vigor desde 2016."},{"id":772,"materia":"pciv","nivel":1,"enunciado":"No processo civil, quem faz o pedido ao juiz é o:","opcoes":["Autor","Réu","Escrivão","Perito"],"explicacao":"O réu é contra quem o pedido é feito."},{"id":773,"materia":"pciv","nivel":1,"enunciado":"A peça que dá início ao processo civil é a:","opcoes":["Petição inicial","Contestação","Sentença","Denúncia"],"explicacao":"Denúncia é a peça da ação penal pública."},{"id":774,"materia":"pciv","nivel":1,"enunciado":"A principal defesa do réu no processo civil é a:","opcoes":["Contestação","Petição inicial","Réplica","Denúncia"],"explicacao":"Nela o réu apresenta toda a matéria de defesa."},{"id":775,"materia":"pciv","nivel":1,"enunciado":"A decisão que encerra a fase de conhecimento em 1º grau é a:","opcoes":["Sentença","Acórdão","Despacho","Citação"],"explicacao":"Acórdão é a decisão colegiada dos tribunais."},{"id":776,"materia":"pciv","nivel":1,"enunciado":"A decisão colegiada de um tribunal chama-se:","opcoes":["Acórdão","Sentença","Despacho","Liminar"],"explicacao":"Art. 204 do CPC."},{"id":777,"materia":"pciv","nivel":1,"enunciado":"O ato que chama o réu ao processo para se defender é a:","opcoes":["Citação","Intimação","Sentença","Penhora"],"explicacao":"A intimação dá ciência de atos do processo."},{"id":778,"materia":"pciv","nivel":1,"enunciado":"Em regra, o recurso cabível contra a sentença é a:","opcoes":["Apelação","Agravo de instrumento","Recurso especial","Reclamação"],"explicacao":"Art. 1.009 do CPC."},{"id":779,"materia":"pciv","nivel":1,"enunciado":"No CPC, os prazos contados em dias computam:","opcoes":["Apenas os dias úteis","Os dias corridos","Apenas fins de semana","Apenas dias de audiência"],"explicacao":"Art. 219 do CPC."},{"id":780,"materia":"pciv","nivel":1,"enunciado":"Em regra, quem representa a parte em juízo é o:","opcoes":["Advogado","Escrivão","Perito","Oficial de justiça"],"explicacao":"É a capacidade postulatória."},{"id":781,"materia":"pciv","nivel":2,"enunciado":"No procedimento comum, qual o prazo para contestar?","opcoes":["15 dias","10 dias","5 dias","30 dias"],"explicacao":"Art. 335 do CPC."},{"id":782,"materia":"pciv","nivel":2,"enunciado":"Qual o prazo para interpor apelação?","opcoes":["15 dias","5 dias","10 dias","30 dias"],"explicacao":"Art. 1.003, § 5º. Os embargos de declaração são a exceção, com 5 dias."},{"id":783,"materia":"pciv","nivel":2,"enunciado":"Qual o prazo dos embargos de declaração no CPC?","opcoes":["5 dias","15 dias","2 dias","10 dias"],"explicacao":"Art. 1.023 do CPC."},{"id":784,"materia":"pciv","nivel":2,"enunciado":"Se o réu não contesta a ação, ocorre a:","opcoes":["Revelia","Prescrição","Litispendência","Perempção"],"explicacao":"Art. 344 do CPC."},{"id":785,"materia":"pciv","nivel":2,"enunciado":"Qual o principal efeito da revelia?","opcoes":["Presumem-se verdadeiros os fatos do autor","Extingue-se o processo sem julgamento","O autor perde o direito de ação","O juiz deve julgar a favor do réu"],"explicacao":"Art. 344, com as exceções do art. 345."},{"id":786,"materia":"pciv","nivel":2,"enunciado":"Contra decisões interlocutórias listadas no art. 1.015 do CPC, cabe:","opcoes":["Agravo de instrumento","Apelação","Embargos infringentes","Recurso extraordinário"],"explicacao":"Os embargos infringentes foram extintos pelo CPC/2015."},{"id":787,"materia":"pciv","nivel":2,"enunciado":"Para a Fazenda Pública, o MP e a Defensoria, os prazos processuais são contados:","opcoes":["Em dobro","Em triplo","Pela metade","Normalmente"],"explicacao":"Arts. 180, 183 e 186 do CPC."},{"id":788,"materia":"pciv","nivel":2,"enunciado":"Antes da contestação, o procedimento comum prevê, em regra:","opcoes":["Audiência de conciliação ou mediação","Sentença de mérito antecipada","Perícia técnica obrigatória","Julgamento de recurso pelo tribunal"],"explicacao":"Art. 334 do CPC."},{"id":789,"materia":"pciv","nivel":2,"enunciado":"Quando se repete uma ação que ainda está em curso, ocorre:","opcoes":["Litispendência","Coisa julgada","Conexão","Revelia"],"explicacao":"Art. 337, § 3º. Se a primeira já tiver decisão definitiva, é coisa julgada."},{"id":790,"materia":"pciv","nivel":2,"enunciado":"Ações com o mesmo pedido ou a mesma causa de pedir são:","opcoes":["Conexas","Idênticas","Litispendentes","Prescritas"],"explicacao":"Art. 55 do CPC."},{"id":791,"materia":"pciv","nivel":3,"enunciado":"A tutela de urgência exige:","opcoes":["Probabilidade do direito e perigo de dano","Prova documental de todos os fatos","Trânsito em julgado de outra ação","Concordância expressa do réu"],"explicacao":"Art. 300 do CPC."},{"id":792,"materia":"pciv","nivel":3,"enunciado":"A tutela da evidência dispensa a demonstração de:","opcoes":["Perigo de dano","Probabilidade do direito","Prova documental","Petição inicial"],"explicacao":"Art. 311 do CPC."},{"id":793,"materia":"pciv","nivel":3,"enunciado":"A coisa julgada material torna a decisão de mérito:","opcoes":["Imutável e indiscutível","Provisória até nova prova","Revogável pelo próprio juiz","Recorrível a qualquer tempo"],"explicacao":"Art. 502 do CPC."},{"id":794,"materia":"pciv","nivel":3,"enunciado":"Qual o prazo da ação rescisória?","opcoes":["2 anos do trânsito em julgado","5 anos da sentença","1 ano da citação","10 anos da publicação"],"explicacao":"Art. 975 do CPC."},{"id":795,"materia":"pciv","nivel":3,"enunciado":"O processo é extinto sem resolução de mérito quando, por exemplo:","opcoes":["Falta legitimidade ou interesse","O juiz acolhe o pedido do autor","O réu reconhece o pedido","O juiz reconhece a prescrição"],"explicacao":"Art. 485, VI. As outras hipóteses são com resolução de mérito (art. 487)."},{"id":796,"materia":"pciv","nivel":3,"enunciado":"O reconhecimento da prescrição gera sentença:","opcoes":["Com resolução de mérito","Sem resolução de mérito","Interlocutória","Nula"],"explicacao":"Art. 487, II, do CPC."},{"id":797,"materia":"pciv","nivel":3,"enunciado":"Quando o comprador, réu na ação, chama o vendedor para responder pela evicção, ocorre:","opcoes":["Denunciação da lide","Chamamento ao processo","Assistência","Oposição"],"explicacao":"Art. 125, I, do CPC."},{"id":798,"materia":"pciv","nivel":3,"enunciado":"No CPC, o incidente de desconsideração da personalidade jurídica é:","opcoes":["Uma intervenção de terceiros","Um recurso ao tribunal","Uma ação autônoma obrigatória","Uma forma de citação"],"explicacao":"Arts. 133 a 137 do CPC."},{"id":799,"materia":"pciv","nivel":3,"enunciado":"O amicus curiae é:","opcoes":["Terceiro que traz subsídios em causa relevante","Curador especial do réu citado por edital","Perito escolhido pelas partes em consenso","Juiz auxiliar do tribunal de origem"],"explicacao":"Art. 138 do CPC."},{"id":800,"materia":"pciv","nivel":3,"enunciado":"Na ordem de preferência da penhora, o primeiro lugar é de:","opcoes":["Dinheiro","Imóveis","Veículos","Ações de empresas"],"explicacao":"Art. 835, I, do CPC."},{"id":801,"materia":"pciv","nivel":4,"enunciado":"O incidente de resolução de demandas repetitivas (IRDR) é julgado:","opcoes":["Pelo órgão do tribunal indicado no regimento","Pelo juiz de 1º grau da causa piloto","Pelo Supremo Tribunal Federal, sempre","Pelo Conselho Nacional de Justiça"],"explicacao":"Art. 978 do CPC."},{"id":802,"materia":"pciv","nivel":4,"enunciado":"A ordem cronológica de julgamento do art. 12 do CPC deve ser seguida:","opcoes":["Preferencialmente","Obrigatoriamente, sem exceção","Apenas nos tribunais superiores","Somente em ações coletivas"],"explicacao":"Redação dada pela Lei 13.256/2016."},{"id":803,"materia":"pciv","nivel":4,"enunciado":"Em regra, os honorários de sucumbência são fixados entre:","opcoes":["10% e 20% da condenação","5% e 10% da condenação","20% e 30% da condenação","1% e 5% da condenação"],"explicacao":"Art. 85, § 2º, do CPC."},{"id":804,"materia":"pciv","nivel":4,"enunciado":"O negócio jurídico processual do art. 190 é admitido em processos que versem sobre direitos que admitam:","opcoes":["Autocomposição","Apenas réu revel","Somente a Fazenda Pública","Apenas ação penal"],"explicacao":"As partes podem ajustar o procedimento às especificidades da causa."},{"id":805,"materia":"pciv","nivel":4,"enunciado":"Não há remessa necessária quando a condenação da União for inferior a:","opcoes":["1.000 salários mínimos","500 salários mínimos","100 salários mínimos","60 salários mínimos"],"explicacao":"Art. 496, § 3º, I. Para estados e capitais são 500; para os demais municípios,