:"afo","nivel":2,"enunciado":"Todas as receitas e despesas devem constar do orçamento. Esse é o princípio da:","opcoes":["Universalidade","Exclusividade","Especificação","Publicidade"],"explicacao":"Art. 2º da Lei 4.320/1964."},{"id":863,"materia":"afo","nivel":2,"enunciado":"A vedação de vincular receita de impostos a órgão, fundo ou despesa é o princípio da:","opcoes":["Não afetação","Unidade","Anualidade","Exclusividade"],"explicacao":"Art. 167, IV, com exceções como saúde e educação."},{"id":864,"materia":"afo","nivel":2,"enunciado":"Na ordem correta, os estágios da despesa são:","opcoes":["Empenho, liquidação e pagamento","Liquidação, empenho e pagamento","Pagamento, empenho e liquidação","Empenho, pagamento e liquidação"],"explicacao":"Arts. 58 a 64 da Lei 4.320/1964."},{"id":865,"materia":"afo","nivel":2,"enunciado":"O empenho é o ato que:","opcoes":["Reserva a dotação e cria a obrigação","Verifica o direito do credor","Entrega o dinheiro ao credor","Arrecada o tributo devido"],"explicacao":"Art. 58 da Lei 4.320/1964."},{"id":866,"materia":"afo","nivel":2,"enunciado":"A liquidação da despesa consiste em:","opcoes":["Verificar o direito do credor","Reservar a dotação orçamentária","Entregar o dinheiro ao credor","Arrecadar o tributo devido"],"explicacao":"Art. 63 da Lei 4.320/1964, com base nos documentos que comprovam o crédito."},{"id":867,"materia":"afo","nivel":2,"enunciado":"Restos a pagar são despesas:","opcoes":["Empenhadas e não pagas até 31/12","Pagas antes do empenho","Previstas para o próximo PPA","Canceladas pelo Tribunal de Contas"],"explicacao":"Art. 36 da Lei 4.320/1964."},{"id":868,"materia":"afo","nivel":2,"enunciado":"Os créditos para despesas imprevisíveis e urgentes, como guerra ou calamidade, são:","opcoes":["Extraordinários","Suplementares","Especiais","Ordinários"],"explicacao":"Art. 167, § 3º, da Constituição."},{"id":869,"materia":"afo","nivel":2,"enunciado":"Os créditos adicionais destinados a reforçar dotação já existente são:","opco